/**
 * The contract pins (OSS-PLAN §2.3): per Herdr version herdr-relay was tested with, what its app home looked like.
 * `pins.json` is generated by `deno task contract:update --tag v<ver>` from `fixtures/contract/<ver>/` and is never
 * edited by hand; the bridge ships it because the fixtures are not part of a release.
 */

import pinsFile from "./pins.json" with { type: "json" };

/** One tested Herdr version's contract surfaces. */
export interface VersionPins {
  /** sha256 of `<appHome>/herdr.d.ts` (the 44 `herdr` functions). */
  herdrDts: string;
  /** sha256 of the `gpui-kit.d.ts` Herdr writes into mod folders (gpui-kit's element and style names). */
  gpuiKitDts: string;
  /** `<appHome>/installed.json`: shipped mod (or `layout:<name>`) → file → Herdr's own 16-hex hash. */
  installed: Readonly<Record<string, Readonly<Record<string, string>>>>;
  /** The names `herdr-app commands` lists, sorted. */
  commands: readonly string[];
}

export interface ContractPins {
  /** Herdr version (`major.minor.patch`) → its pins. */
  versions: Readonly<Record<string, VersionPins>>;
}

/** The pins bundled with this bridge. */
export const CONTRACT_PINS: ContractPins = { versions: pinsFile.versions };

/**
 * The oldest Herdr herdr-relay supports at all (the shipped profiles' `requires.herdr`); older ones get the
 * "unsupported" banner and the bridge still runs.
 */
export const SUPPORTED_FROM = "0.1.13";

const VERSION = /^(\d+)\.(\d+)\.(\d+)(?:-(.+))?$/;

/** `major.minor.patch[-pre]` order; a pre-release sorts before its release. Non-versions compare as equal. */
export function compareVersions(a: string, b: string): number {
  const x = VERSION.exec(a);
  const y = VERSION.exec(b);
  if (x === null || y === null) return 0;
  for (let i = 1; i <= 3; i++) {
    const d = Number(x[i]) - Number(y[i]);
    if (d !== 0) return Math.sign(d);
  }
  if (x[4] === y[4]) return 0;
  if (x[4] === undefined) return 1;
  if (y[4] === undefined) return -1;
  return x[4] < y[4] ? -1 : 1;
}

/** The pinned versions, oldest first. */
export function testedVersions(pins: ContractPins = CONTRACT_PINS): string[] {
  return Object.keys(pins.versions).sort(compareVersions);
}
